def sembrar_frases(apps, schema_editor):
    FraseGratitud = apps.get_model('dashboard', 'FraseGratitud')
    for dia, texto, autor, obra, anio in FRASES:
        FraseGratitud.objects.update_or_create(
            dia=dia,
            defaults={'texto': texto, 'autor': autor, 'obra': obra, 'anio': anio},
        )


def borrar_frases(apps, schema_editor):
    FraseGratitud = apps.get_model('dashboard', 'FraseGratitud')
    FraseGratitud.objects.filter(dia__in=[f[0] for f in FRASES]).delete()


